$share.data = {};
var real_status = status;
doServiceAjax('sepoa.svc.seal.SepoaSealManagementService', 'CONNECTION', 'doDocumentDetail', {
    DOC_NO: docNo,
    MANAGE_NUMBER: manageNo,
    APPLY_TYPE: "NE",
    COMPANY_CODE: companyCode
}, function(so) {
    if (so.status == 1) {
        var soResult = new SepoaFormater(so.result[0]);
        var manageNumber = soResult.getArrayMap()[0].MANAGE_NUMBER;
        var docNo = soResult.getArrayMap()[0].DOC_NO;

        $share.data.MANAGE_NUMBER = manageNumber;
        $share.data.DOC_NO = docNo;

        var status;
        if (route == 'APP') {
            status = 'DETAILAPP';
        } else if (route == 'LIST') {
            status = 'DETAIL';
        } else {
            status = soResult.getArrayMap()[0].STATUS;
        }
        setModeByStatus(status);

        formObj.dataMapper(new SepoaFormater(so.result[0]));
        doLoadImg(manageNo + "_" + docNo);

        formInitSetting();

        return true;
    } else {
        Alert(Sepoa.cache.text.get('MESSAGE.1002'));
        doBack();
        return false;
    }
});
if (sUtils.workflow.check('US1681189618235')) {
    doLoadAppData(manageNo, docNo, companyCode);
}


//인감목록 -> 인감정보 조회시
$share.data = {};
doServiceAjax('sepoa.svc.seal.SepoaSealManagementService', 'CONNECTION', 'doSealDetail', {
    MANAGE_NUMBER: manageNo,
    COMPANY_CODE: companyCode
}, function(so) {
    if (so.status == 1) {
        $share.data.MANAGE_NUMBER = manageNo;
        formObj.dataMapper(new SepoaFormater(so.result[0]));
        doLoadImg(manageNo);
        setModeByStatus('DETAIL')
        formObj.setdisable('SELECT_IMG_BTN', true);
        return true;
    } else {
        Alert(so.message);
        doBack();
        return false;
    }
});
if (sUtils.workflow.check('US1681189618235')) {
    doLoadAppData(manageNo, null, companyCode);
}


gridObj.clearAll();

var appParamsObj = {
	MANAGE_NO : manageNo,
	MODE: "SEAL_APPROVAL",
	TYPE: "CREATE_INFO",
	COMPANY_CODE: companyCode
}

if(docNo) {
	appParamsObj["DOC_NO"] = docNo;
}

doServiceAjax('sepoa.svc.seal.SepoaSealManagementService', 'CONNECTION', 'doAppDetail', appParamsObj, function(so) {
    if (so.status == 1) {
        var resultObj = JSON.parse(so.result[0]);
       	if(resultObj["CURRENT_APPROVER"]) {
       		for(let i of resultObj["CURRENT_APPROVER"]) {
       			var maxRowId = dhx4.newId();
       			gridObj.addRow(maxRowId, '', gridObj.getRowsNum());
                gridObj.cells(maxRowId, gridObj.getColIndexById('APP_USER_ID')).setValue(i.APP_USER_ID);
                gridObj.cells(maxRowId, gridObj.getColIndexById('APP_USER_NAME')).setValue(i.USER_NAME_LOC);
                gridObj.cells(maxRowId, gridObj.getColIndexById('APP_USER_DEPT')).setValue(i.APP_USER_DEPT);
                gridObj.cells(maxRowId, gridObj.getColIndexById('APP_USER_DEPT_NAME')).setValue(i.DEPT_NAME_LOC);
                gridObj.cells(maxRowId, gridObj.getColIndexById('APP_SORT')).setValue(i.APP_SORT);
       		}
       	}
    } else {
        Alert(so.message);
        doBack();
        return false;
    }
});


$share.data = {};
doServiceAjax('sepoa.svc.seal.SepoaSealManagementService', 'CONNECTION', 'doSealDetail', {
    MANAGE_NUMBER: manageNo,
}, function(so) {
    if (so.status == 1) {
        $share.data.MANAGE_NUMBER = manageNo;

        var soResult = new SepoaFormater(so.result[0]);
        formObj.dataMapper(soResult);

        $seal_type = soResult.dataMap.SEAL_TYPE;

        doLoadImg(manageNo);
        setModeByStatus('UPDATE')
        return true;
    } else {
        Alert(Sepoa.cache.text.get('MESSAGE.1002'));
        doBack();
        return false;
    }
});

