    Alert(Sepoa.cache.text.get('SLM_123.MESSAGE008')); //제목을 입력해주세요.
    return;
}

var files = $sealImgFile;
var config = {
    multiple: false,
    url: window.CONTEXT_NAME + '/SepoaActionController.sux',
    ext: ['jpeg', 'jpg', 'png'],
    on: {
        callback: function(res) {
            if (res.status == "1") {
                if (callbackObj) {
                    callbackObj.CALLBACK(callbackObj.CALLBACK_PARMETER);
                } else {
                    Alert(Sepoa.cache.text.get('MESSAGE.0001'));
                }
            } else {
                Alert(res.message);
            }
        }
    }
}

var appUserArr = new Array();
if (sUtils.workflow.check('US1681189618235')) {
    if (gridObj.getRowsNum() > 0) {
        var infoFlag = true;
        var appDataFlag = [];
        gridObj.forEachRowA(function(id) {
            var userId = gridObj.cells(id, gridObj.getColIndexById("APP_USER_ID")).getValue();
            var userDept = gridObj.cells(id, gridObj.getColIndexById("APP_USER_DEPT")).getValue();
            var appSort = gridObj.cells(id, gridObj.getColIndexById("APP_SORT")).getValue();

            if (userId == '' || userDept == '' || appSort == '' || !checkNumber(appSort)) {
                infoFlag = false;
            }
            appDataFlag.push(infoFlag)
        });
        if (appDataFlag.indexOf(false) > -1) {
            Alert("결재자 등록 정보가 올바르게 작성되지 않았습니다.");
            return false;
        }

        var mngNumber = $share.data.MANAGE_NUMBER;
        gridObj.forEachRowA(function(id) { //결재자 등록 정보 수집
            var userData = {};
            userData.KEY_NUMBER = mngNumber;
            userData.APP_USER_ID = gridObj.cells(id, gridObj.getColIndexById('APP_USER_ID')).getValue();
            userData.APP_USER_NAME = gridObj.cells(id, gridObj.getColIndexById('APP_USER_NAME')).getValue();
            userData.APP_USER_DEPT = gridObj.cells(id, gridObj.getColIndexById('APP_USER_DEPT')).getValue();
            userData.APP_USER_DEPT_NAME = gridObj.cells(id, gridObj.getColIndexById('APP_USER_DEPT_NAME')).getValue();
            userData.APP_SORT = gridObj.cells(id, gridObj.getColIndexById('APP_SORT')).getValue();
            appUserArr.push(userData);
        });
    }
}

var basic_info = getCustomFormData();
basic_info.MANAGE_DOC_NO = $share.data.MANAGE_NUMBER + '_' + $share.data.DOC_NO;

var serviceData = {
    parameter: {
        basic_info: basic_info
    },
    APP_USER_LIST: appUserArr
};

var params = {
    module: "seal.management",
    action: "doCreateService",
    CONNECTION: "TRANSACTION",
    CURRENT_PRC: "CREATE",
    MANAGE_DOC_NO: $share.data.MANAGE_NUMBER + '_' + $share.data.DOC_NO,
    SEAL_DATA: JSON.stringify(serviceData)
}

if (callbackObj || route == 'APP') {
